        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var finalNRR = lastResult.nrr || 0;
            var finalLtvCac = lastResult.ltvCacRatio || 0;
            var finalPayback = lastResult.cacPayback || 99;
            var finalRunway = lastResult.runway || 0;
            var finalMRR = lastResult.mrr || 0;
            var seriesBScore = lastResult.seriesBScore || 0;

            var qualified = finalNRR >= 110 && finalLtvCac >= 3.0 && finalPayback <= 18 && finalRunway >= 6;

            var insights = [];
            if (finalNRR >= 110) {
                insights.push('NRR above 110% — existing customers are driving organic growth.');
            } else {
                insights.push('NRR below 110% — focus on retention and upsell motions to unlock organic growth.');
            }
            if (finalLtvCac >= 3.0) {
                insights.push('LTV:CAC above 3x — strong unit economics justify continued growth investment.');
            } else {
                insights.push('LTV:CAC below 3x — improve ICP targeting or reduce CAC to meet investor thresholds.');
            }
            if (finalPayback <= 18) {
                insights.push('CAC payback within 18 months — healthy cash conversion cycle.');
            } else {
                insights.push('CAC payback exceeds 18 months — high burn risk for growth-stage company.');
            }

            return {
                qualified,
                finalNRR,
                finalLtvCac,
                finalPayback,
                finalRunway,
                finalMRR,
                seriesBScore,
                performance: qualified ? 'Series B Ready' : seriesBScore >= 50 ? 'Progressing' : 'Needs Work',
                insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.runwayMonths < 4) return window.mySimulation.t('hint_low_runway');
            if (results.nrr < 95) return window.mySimulation.t('hint_low_nrr');
            if (results.ltvCacRatio < 1.5) return window.mySimulation.t('hint_low_ltv_cac');
            if (results.cacPayback > 24) return window.mySimulation.t('hint_high_payback');
            if (results.seriesBScore === 100) return window.mySimulation.t('hint_series_b_ready');
            return null;
        }

